<script setup lang="ts">
import {ref,onMounted,watch} from 'vue';import {gsap} from 'gsap';import {ScrollTrigger} from 'gsap/ScrollTrigger';import {useMotion,type MotionProps} from '../../lib/useMotion';import {progress} from '../../lib/runtime.mjs';
const props=defineProps<MotionProps>();const {active,scope}=useMotion(props);const root=ref<HTMLElement>();const amount=ref(0);let ctx:ReturnType<typeof gsap.context>|undefined;
function sync(){ctx?.revert();ctx=undefined;if(!root.value)return;if(active.value&&props.variant!=='progress'){gsap.registerPlugin(ScrollTrigger);ctx=gsap.context(()=>gsap.to('.object',{y:props.variant==='parallax'?-60:0,rotation:props.variant==='scrub'?140:0,ease:'none',scrollTrigger:{trigger:root.value!.querySelector('.scroll-content'),scroller:root.value,start:'top top',end:'bottom bottom',scrub:true}}),root.value);}}
